import sys

def solve(patterns, text):
    from collections import deque
    trie = [{}]; fail = [0]; output = [[]]
    for idx, p in enumerate(patterns):
        node = 0
        for ch in p:
            if ch not in trie[node]: trie[node][ch]=len(trie); trie.append({}); fail.append(0); output.append([])
            node = trie[node][ch]
        output[node].append(idx)
    q = deque()
    for ch, child in trie[0].items(): fail[child]=0; q.append(child)
    while q:
        node = q.popleft()
        for ch, child in trie[node].items():
            f=fail[node]
            while f!=0 and ch not in trie[f]: f=fail[f]
            fail[child]=trie[f].get(ch,0)
            if fail[child]==child: fail[child]=0
            output[child]=output[child]+output[fail[child]]; q.append(child)
    counts=[0]*len(patterns); node=0
    for ch in text:
        while node!=0 and ch not in trie[node]: node=fail[node]
        node=trie[node].get(ch,0)
        for pidx in output[node]: counts[pidx]+=1
    return "\n".join(map(str,counts))

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    k = int(lines[0].strip())
    patterns = [lines[i+1].strip() for i in range(k)]
    text = lines[k+1].strip() if k+1 < len(lines) else ""
    print(solve(patterns, text))

